def newman_prime(n):
    def is_prime(num):
        if num <= 1:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    def nsw_number(k):
        if k == 0:
            return 2
        elif k == 1:
            return 3
        else:
            return 2 * nsw_number(k - 1) + nsw_number(k - 2)

    count = 0
    i = 0
    while True:
        if is_prime(nsw_number(i)):
            count += 1
            if count == n:
                return nsw_number(i)
        i += 1
